const previousNodeData = $('IF Emails Found').first();
const currentItems = $input.all();

// Return all current items with the previous node data merged in
return currentItems.map(item => ({
  json: {
    ...previousNodeData.json,  // Data from previous node
    ...item.json,              // Data from current node (overwrites if keys conflict)
  },
  binary: item.binary || previousNodeData.binary,  // Keep binary data
}));

/*
 * N8N CODE NODE - INVOICE PARSER (Pure JavaScript - No TypeScript)
 * =================================================================
 * 
 * This version uses plain JavaScript without TypeScript types
 * to avoid any type-related errors in n8n.
 * 
 * SETUP IN N8N:
 * 1. Read/Binary Files node → Read your CSV/TXT file
 * 2. Code node → Paste this entire script
 * 3. Set "Mode" to "Run Once for All Items"
 */

// Get input data from n8n
const items = $input.all();
let csvText = '';
let inputFilename = '';

// Extract CSV text and filename from various possible input formats
if (items[0].json.data) {
    csvText = items[0].json.data;
} else if (items[0].binary && items[0].binary.data) {
    csvText = Buffer.from(items[0].binary.data.data, 'base64').toString('utf-8');
} else if (items[0].json.content) {
    csvText = items[0].json.content;
} else {
    // Check if data is in object key format (like NS_0200597867_597867_20251105034147)
    const keys = Object.keys(items[0].json);
    if (keys.length > 0 && keys[0] !== 'data' && keys[0] !== 'content') {
        inputFilename = keys[0];
        csvText = items[0].json[keys[0]];
    } else {
        throw new Error('No CSV data found. Expected data in json.data, binary.data, or json.content');
    }
}

// Helper function to get day name and month name
function getDateDetails(dateStr) {
    const parts = dateStr.split('/');
    const day = parts[0];
    const month = parts[1];
    const year = parts[2];

    const dateObj = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));

    const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const dayName = dayNames[dateObj.getDay()];

    const monthNames = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
    ];
    const monthName = monthNames[dateObj.getMonth()];

    return {
        day: day,
        dayName: dayName,
        month: monthName,
        monthNumber: month,
        year: year
    };
}

// Parse CSV into array of objects
function parseCSV(text) {
    const lines = text.trim().split(/\r?\n/);
    const headers = lines[0].split(',').map(function(h) { return h.trim(); });
    const transactions = [];

    for (let i = 1; i < lines.length; i++) {
        if (!lines[i].trim()) continue;

        const values = lines[i].split(',').map(function(v) { return v.trim(); });
        const transaction = {};

        for (let j = 0; j < headers.length; j++) {
            transaction[headers[j]] = values[j] || '';
        }

        transactions.push(transaction);
    }

    return transactions;
}

// Group and calculate totals by invoice date
function calculateInvoices(transactions) {
    const groups = {};

    for (let i = 0; i < transactions.length; i++) {
        const txn = transactions[i];
        const invoiceDate = txn['INVCE DATE'];

        if (!Object.prototype.hasOwnProperty.call(groups, invoiceDate)) {
            groups[invoiceDate] = {
                transactions: [],
                productNet: 0,
                productGST: 0,
                productTotal: 0,
                feeNet: 0,
                feeGST: 0,
                feeTotal: 0
            };
        }

        groups[invoiceDate].transactions.push(txn);
        groups[invoiceDate].productNet += parseFloat(txn['PRD EX GST']) || 0;
        groups[invoiceDate].productGST += parseFloat(txn['GST']) || 0;
        groups[invoiceDate].productTotal += parseFloat(txn['PRD INCGST']) || 0;
        groups[invoiceDate].feeNet += parseFloat(txn['TRN FEE']) || 0;
        groups[invoiceDate].feeGST += parseFloat(txn['FEEGST']) || 0;
        groups[invoiceDate].feeTotal += parseFloat(txn['FEE+GST']) || 0;
    }

    const results = [];
    const invoiceDates = Object.keys(groups);

    for (let i = 0; i < invoiceDates.length; i++) {
        const invoiceDate = invoiceDates[i];
        const group = groups[invoiceDate];
        const dateDetails = getDateDetails(invoiceDate);

        // Net = Product Ex GST + Transaction Fee (no GST)
        const net = group.productNet + group.feeNet;

        // GST = Product GST + Fee GST
        const gst = group.productGST + group.feeGST;

        // Amount = Net + GST
        const amount = net + gst;

        // Get account number from first transaction (all transactions have same account)
        const account = group.transactions[0]['ACCT#'] || '';

        // Extract invoice number from input filename if available
        // Format: NS_0200597867_597867_20251105034147 -> invoice number is 20251105
        let invoiceNo = 'INV-' + dateDetails.year + dateDetails.monthNumber + dateDetails.day;
        if (inputFilename) {
            const parts = inputFilename.split('_');
            // Invoice number is typically the 4th part (after NS, account prefix, account number)
            if (parts.length >= 4) {
                // Extract first 8 digits from the last part (20251105 from 20251105034147)
                const lastPart = parts[3];
                const invoiceNumFromFile = lastPart.substring(0, 8);
                if (invoiceNumFromFile && invoiceNumFromFile.length === 8) {
                    invoiceNo = invoiceNumFromFile;
                }
            }
        }

        // Use inputFilename as filename if available, otherwise generate one
        const filename = inputFilename || 'invoice_' + dateDetails.year + '_' + dateDetails.monthNumber + '_' + dateDetails.day + '.pdf';

        results.push({
            inputFilename: inputFilename,
            account: account,
            filename: filename,
            date: invoiceDate,
            day: dateDetails.day,
            dayName: dateDetails.dayName,
            month: dateDetails.month,
            monthNumber: dateDetails.monthNumber,
            year: dateDetails.year,
            invoiceNo: invoiceNo,
            transactionCount: group.transactions.length,
            net: parseFloat(net.toFixed(2)),
            gst: parseFloat(gst.toFixed(2)),
            amount: parseFloat(amount.toFixed(2)),
            productNet: parseFloat(group.productNet.toFixed(2)),
            productGST: parseFloat(group.productGST.toFixed(2)),
            productTotal: parseFloat(group.productTotal.toFixed(2)),
            feeNet: parseFloat(group.feeNet.toFixed(2)),
            feeGST: parseFloat(group.feeGST.toFixed(2)),
            feeTotal: parseFloat(group.feeTotal.toFixed(2)),
            transactions: group.transactions
        });
    }

    return results;
}

// Execute
const transactions = parseCSV(csvText);
const invoices = calculateInvoices(transactions);

// Return as n8n items
return invoices.map(function(invoice) { 
    return { json: invoice }; 
});

// ============================================================================
// CHECK PREVIOUS DAY RECORD - Extract Date from Filename
// ============================================================================
// Purpose: Check if yesterday's record exists by comparing dates in filenames
// Logic: Extract date from filename (e.g., NS_...20251105... → 20251105)
//        Then check if previous day's file exists in Airtable
// ============================================================================

// Get data from previous nodes
const extractedData = $('Extract & Calculate Data').first().json;
const searchResults = $input.all();

// ===== HELPER FUNCTIONS =====

// Extract date from filename (e.g., "NS_0200597867_597867_20251105034147" → "20251105")
function extractDateFromFilename(filename) {
  if (!filename) return null;

  // Pattern: NS_XXXXXXXXXX_XXXXXX_YYYYMMDDHHMMSS
  // Extract the date part (YYYYMMDD) which is 8 digits after the last underscore before time
  const match = filename.match(/(\d{8})\d{6}$/);
  return match ? match[1] : null;
}

// Convert YYYYMMDD to Date object
function parseYYYYMMDD(dateStr) {
  if (!dateStr || dateStr.length !== 8) return null;
  const year = parseInt(dateStr.substring(0, 4));
  const month = parseInt(dateStr.substring(4, 6)) - 1; // Month is 0-indexed
  const day = parseInt(dateStr.substring(6, 8));
  return new Date(year, month, day);
}

// Convert Date object to YYYYMMDD string
function formatToYYYYMMDD(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}${month}${day}`;
}

// Get previous day in YYYYMMDD format
function getPreviousDayYYYYMMDD(dateStr) {
  const currentDate = parseYYYYMMDD(dateStr);
  if (!currentDate) return null;

  const previousDate = new Date(currentDate);
  previousDate.setDate(previousDate.getDate() - 1);

  return formatToYYYYMMDD(previousDate);
}

// Format YYYYMMDD to readable format (YYYY-MM-DD)
function formatToReadable(dateStr) {
  if (!dateStr || dateStr.length !== 8) return dateStr;
  return `${dateStr.substring(0, 4)}-${dateStr.substring(4, 6)}-${dateStr.substring(6, 8)}`;
}

// ===== MAIN LOGIC =====

// Extract current record information
const currentFileName = extractedData.filename;
const currentDateFromFile = extractDateFromFilename(currentFileName); // e.g., "20251105"
const currentDateReadable = formatToReadable(currentDateFromFile); // e.g., "2025-11-05"

// Calculate previous day date
const previousDayDate = getPreviousDayYYYYMMDD(currentDateFromFile); // e.g., "20251104"
const previousDayReadable = formatToReadable(previousDayDate); // e.g., "2025-11-04"

// Initialize check variables
let currentRecordExists = false;
let currentRecordId = null;

let previousDayRecordExists = false;
let previousDayRecordId = null;
let previousDayFileName = null;

// Search through all Airtable records
if (searchResults && searchResults.length > 0) {
  for (const result of searchResults) {
    const record = result.json;

    // Get filename from record
    const recordFileName = record.fields?.['File Name'] || record['File Name'];

    if (!recordFileName) continue;

    // Extract date from this record's filename
    const recordDate = extractDateFromFilename(recordFileName);

    // Check if current record exists (exact filename match)
    if (recordFileName === currentFileName) {
      currentRecordExists = true;
      currentRecordId = record.id;
    }

    // Check if previous day record exists (date match)
    if (recordDate === previousDayDate) {
      previousDayRecordExists = true;
      previousDayRecordId = record.id;
      previousDayFileName = recordFileName;
    }
  }
}

// ===== DECISION LOGIC =====

let shouldInsert = false;
let reason = '';
let status = '';

if (currentRecordExists) {
  // Current record already exists - SKIP
  shouldInsert = false;
  reason = `Current record already exists in Airtable (ID: ${currentRecordId})`;
  status = 'DUPLICATE_SKIPPED';
} else if (!previousDayRecordExists) {
  // Previous day record is missing - SKIP
  shouldInsert = false;
  reason = `Previous day record (${previousDayReadable}) is missing. Cannot insert today's record until yesterday's data is available.`;
  status = 'PREVIOUS_DAY_MISSING';
} else {
  // All conditions met - INSERT
  shouldInsert = true;
  reason = `Previous day record (${previousDayReadable}) exists. Ready to insert today's record.`;
  status = 'READY_TO_INSERT';
}

// ===== PREPARE OUTPUT =====

const result = {
  // ===== Control Flags =====
  shouldInsert: shouldInsert,
  currentRecordExists: currentRecordExists,
  previousDayRecordExists: previousDayRecordExists,

  // ===== Current Record Info =====
  currentFileName: currentFileName,
  currentDate: currentDateFromFile,
  currentDateReadable: currentDateReadable,
  currentRecordId: currentRecordId,

  // ===== Previous Day Info =====
  previousDayDate: previousDayDate,
  previousDayReadable: previousDayReadable,
  previousDayRecordId: previousDayRecordId,
  previousDayFileName: previousDayFileName,

  // ===== Data for Airtable =====
  fields: {
    'File Name': currentFileName,
    'Gross': extractedData.amount,
    'GST': extractedData.gst,
    'Net': extractedData.net,
    'Last Modified': new Date().toISOString().split('T')[0]
  },

  // ===== Status =====
  status: status,
  reason: reason,
  message: getStatusMessage(status, currentFileName, previousDayReadable, currentRecordId, previousDayFileName),

  // ===== Summary =====
  summary: {
    currentFile: currentFileName,
    currentDate: currentDateReadable,
    previousDate: previousDayReadable,
    canInsert: shouldInsert,
    blockReason: shouldInsert ? null : reason,
    totalRecordsSearched: searchResults.length
  },

  // ===== Metadata =====
  metadata: {
    checkTimestamp: new Date().toISOString(),
    workflowName: 'Daily NS file upload',
    nodeVersion: '2.1.0'
  }
};

// Helper function to generate status messages
function getStatusMessage(status, fileName, previousDay, recordId, previousFileName) {
  switch(status) {
    case 'DUPLICATE_SKIPPED':
      return `⚠️ Duplicate detected: Record for ${fileName} already exists (ID: ${recordId}). Skipping insertion.`;
    case 'PREVIOUS_DAY_MISSING':
      return `🚫 Cannot insert ${fileName}. Previous day (${previousDay}) record is missing in Airtable. Please ensure data continuity.`;
    case 'READY_TO_INSERT':
      return `✅ Previous day record found (${previousFileName}). Ready to insert ${fileName}.`;
    default:
      return 'Unknown status';
  }
}

// ===== CONSOLE LOGGING =====
console.log('═══════════════════════════════════════════════════════════════');
console.log('🔍 PREVIOUS DAY RECORD CHECK (Filename-Based Date Extraction)');
console.log('═══════════════════════════════════════════════════════════════');
console.log('📁 Current File:', currentFileName);
console.log('📅 Current Date (from filename):', currentDateFromFile, '→', currentDateReadable);
console.log('📅 Previous Date (calculated):', previousDayDate, '→', previousDayReadable);
console.log('───────────────────────────────────────────────────────────────');
console.log('🔍 Current Record Check:');
console.log('   ├─ Exists:', currentRecordExists);
if (currentRecordExists) {
  console.log('   └─ Record ID:', currentRecordId);
}
console.log('───────────────────────────────────────────────────────────────');
console.log('📋 Previous Day Record Check:');
console.log('   ├─ Exists:', previousDayRecordExists);
if (previousDayRecordExists) {
  console.log('   ├─ Record ID:', previousDayRecordId);
  console.log('   └─ File Name:', previousDayFileName);
} else {
  console.log('   └─ Not found for date:', previousDayReadable);
}
console.log('───────────────────────────────────────────────────────────────');
console.log('✅ Should Insert:', shouldInsert);
console.log('📊 Status:', status);
console.log('💬 Reason:', reason);
console.log('───────────────────────────────────────────────────────────────');
console.log('📈 Records Searched:', searchResults.length);
console.log('═══════════════════════════════════════════════════════════════');

return result;

// ============================================================================
// LOGIC SUMMARY:
// ============================================================================
// 1. Extract date from current filename: NS_...20251105... → 20251105
// 2. Calculate previous day: 20251105 → 20251104
// 3. Check if current record exists (exact filename match) → SKIP if yes
// 4. Check if previous day record exists (date in filename) → SKIP if no
// 5. If previous day exists AND current doesn't → INSERT
// ============================================================================

// Get all input records
const items = $input.all();

// ===== Helper Functions =====

// Extract date (YYYYMMDD) from File Name
function getDateFromFileName(fileName) {
  const match = fileName.match(/(\d{8})\d{6}$/);
  if (!match) return null;
  const dateStr = match[1];
  const year = parseInt(dateStr.substring(0, 4));
  const month = parseInt(dateStr.substring(4, 6)) - 1;
  const day = parseInt(dateStr.substring(6, 8));
  return new Date(year, month, day);
}

// Convert date to "YYYY-MM-DD"
function formatDate(d) {
  return d.toISOString().split('T')[0];
}

// Month name lookup
function getMonthName(date) {
  const months = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];
  return months[date.getMonth()];
}

// ===== Main Logic =====

// Parse all file dates
const records = items
  .map(i => ({
    file: i.json["File Name"],
    gross: i.json.Gross,
    date: getDateFromFileName(i.json["File Name"])
  }))
  .filter(r => r.date);

// Sort by date
records.sort((a, b) => a.date - b.date);

// Group by month
const grouped = {};
for (const r of records) {
  const monthName = getMonthName(r.date);
  if (!grouped[monthName]) grouped[monthName] = [];
  grouped[monthName].push(r);
}

// ===== Check Missing Days =====
let missingDays = [];

for (const month in grouped) {
  const monthRecords = grouped[month];
  const allDates = monthRecords.map(r => r.date);
  const minDate = new Date(Math.min(...allDates));
  const maxDate = new Date(Math.max(...allDates));

  // Loop through each date in range to find gaps
  for (let d = new Date(minDate); d <= maxDate; d.setDate(d.getDate() + 1)) {
    const exists = allDates.some(date => formatDate(date) === formatDate(d));
    if (!exists) missingDays.push(formatDate(d));
  }
}

// ===== Output =====
if (missingDays.length > 0) {
  // Return warning for email node
  return [
    {
      json: {
        status: "MISSING_DAYS",
        missingDays,
        message: `Missing record(s) for: ${missingDays.join(", ")}`
      }
    }
  ];
} else {
  // Calculate totals if complete
  const output = Object.entries(grouped).map(([month, records]) => ({
    Month: month,
    "NS Files": parseFloat(
      records.reduce((sum, r) => sum + (r.gross || 0), 0).toFixed(2)
    )
  }));

  return output.map(o => ({
    json: {
      status: "COMPLETE",
      Month: o.Month,
      "NS Files": o["NS Files"]
    }
  }));
}
